/*
 * Aviso de que o `composer update` não vai trazer a próxima versão do tema: a
 * constraint do composer.json do fórum trava (`^0.1.11` em 0.x, ou uma versão
 * exata). Quem diz é o backend (src/Update/UpdateBlocker), só para admin.
 */
import app from 'flarum/admin/app';
const KEY = 'ramon-canela.admin.settings.shell';
const COMMAND = 'composer require ramon/canela:"*" -W';
const UpdateNotice = {
  view() {
    const constraint = app.forum.attribute('canelaUpdateBlocker');
    if (!constraint) return null;
    return m("div", {
      className: "CanelaAdmin-notice CanelaAdmin-updateNotice",
      role: "status"
    }, m("i", {
      className: "fas fa-triangle-exclamation",
      "aria-hidden": "true"
    }), m("span", null, app.translator.trans(`${KEY}.update_blocked`, {
      constraint: m("code", null, `"ramon/canela": "${constraint}"`)
    }), ' ', app.translator.trans(`${KEY}.update_blocked_fix`), m("code", {
      className: "CanelaAdmin-updateCommand"
    }, COMMAND)));
  }
};
export default UpdateNotice;
flarum.reg.add('ramon-canela', 'admin/components/UpdateNotice', UpdateNotice);